function routeURL(key){const path=window.siteRoutes.find(r=>r.key===key)?.path||'/';return window.siteLanguage==='en'?'/en'+path:path;}
function siteLinks(html){const result=html.replace(/href="#\/([^"]*)"/g,(_,key)=>'href="'+routeURL(key)+'"').replace(/href="caderneta\/index.html"/g,'href="/caderneta/"');return window.siteLanguage==='en'?result.replace(/href="\/(?!en(?:\/|")|assets\/|api\/)([^"]*)"/g,(_,path)=>'href="/en/'+path+'"'):result;}
const photo='https://images.unsplash.com/photo-1500382017468-9049fed747ef?auto=format&fit=crop&w=2200&q=85';
const projects=[{id:'agrario',name:'Agrário',type:'Portal',title:'O próximo capítulo<br>do sector agrário.',desc:'Um portal do portefólio Inbytes dedicado ao sector agrário.',cta:'Conheça a solução',image:true},{id:'jmembro',name:'JMembro',type:'Sistema de gestão',title:'Mais ligação.<br>Melhor gestão.',desc:'Membros, quotas e histórico de contribuições numa plataforma de gestão.',cta:'Conheça a solução'},{id:'sinpocaf',name:'SINPOCAF',type:'Website',title:'Uma presença digital<br>com propósito.',desc:'Conheça o website do SINPOCAF, um projeto do portefólio Inbytes.',cta:'Explore o projeto'},{id:'sintrat',name:'SINTRAT',type:'Website',title:'Tecnologia ao serviço<br>das organizações.',desc:'Uma presença na web para o SINTRAT, no sector dos transportes.',cta:'Explore o projeto'}];
const services=[['Desenvolvimento Web','Websites profissionais e adaptados aos diferentes dispositivos.'],['Sistemas à medida','Soluções para organizar informação e apoiar os processos da sua organização.'],['Aplicações móveis','Experiências móveis desenhadas para os utilizadores e o contexto do negócio.'],['Consultoria tecnológica','Apoio na escolha e implementação de soluções tecnológicas.']];
