for(const p of projects){p.group=['agrario','casas'].includes(p.id)?'portais':['jmembro','caderneta'].includes(p.id)?'produtos':'websites';if(['jmembro','sinpocaf','sintrat','casas'].includes(p.id)){p.photo='/assets/'+p.id+'-hero.jpg';p.alt={jmembro:'Equipa administrativa a trabalhar num escritório — imagem gerada por IA',sinpocaf:'Logística ferroviária e portuária — imagem gerada por IA',sintrat:'Transporte rodoviário — imagem gerada por IA',casas:'Arquitetura residencial — imagem gerada por IA'}[p.id];}}
Object.assign(projects.find(p=>p.id==='jmembro'),{name:'JMembros',desc:'Membros, empresas, contribuições e ocorrências. Informação organizada para uma gestão mais próxima dos associados.'});
Object.assign(projects.find(p=>p.id==='agrario'),{desc:'Plataforma de divulgação e promoção da comercialização agrícola em Moçambique.'});
projects.find(p=>p.id==='sintrat').external='https://www.sintrat.org.mz';projects.find(p=>p.id==='sinpocaf').external='https://www.sinpocaf.org.mz';
projects.sort((a,b)=>['jmembro','caderneta','agrario','casas','sinpocaf','sintrat'].indexOf(a.id)-['jmembro','caderneta','agrario','casas','sinpocaf','sintrat'].indexOf(b.id));
projects.push(...[{"id": "sinpeoc", "name": "SINPEOC", "type": "Website", "group": "websites", "banner": true, "external": "https://www.sinpeoc.org.mz", "photo": "/assets/sinpeoc-site.jpg", "alt": "Atividade portuária — imagem do website SINPEOC", "desc": "Website institucional do sindicato dos profissionais de estiva e ofícios correlativos em Moçambique.", "title": "Uma voz mais próxima.<br>Uma presença mais forte.", "cta": "Explore o projeto", "caseIntro": "O SINPEOC representa profissionais de estiva e ofícios correlativos. O website apresenta a organização, os serviços aos associados e os caminhos para participação e contacto.", "caseFeatures": [["Organização sindical", "Informação institucional e representação dos trabalhadores."], ["Serviços aos membros", "Defesa de direitos, assistência sindical e jurídica."], ["Documentos e participação", "Acesso a documentos e informação sobre filiação."], ["Atividade e contactos", "Divulgação de eventos e canais de contacto."]]}, {"id": "sweetandsalt", "name": "Sweet & Salt", "type": "Website", "group": "websites", "banner": false, "external": "https://www.sweetandsalt.co.mz", "photo": "/assets/sweetandsalt-website.jpg", "alt": "Captura da página inicial do website Sweet & Salt", "desc": "Website da Sweet & Salt, com catálogo de doces e salgados e percurso de encomenda online.", "title": "Sweet & Salt", "cta": "Explore o projeto", "caseIntro": "A Sweet & Salt apresenta bolos, biscoitos e salgados para diferentes ocasiões. O website permite explorar o catálogo, adicionar produtos ao carrinho e indicar os detalhes da encomenda.", "caseFeatures": [["Catálogo de produtos", "Categorias, pesquisa e apresentação dos produtos."], ["Carrinho e encomenda", "Seleção de produtos e indicação dos detalhes do pedido."], ["Opções de pagamento", "Informação sobre os métodos de pagamento disponíveis."], ["Marca e contacto", "Apresentação da marca e canais para falar com a loja."]]}, {"id": "indicofishfarm", "name": "Indico Fish Farm", "type": "Website", "group": "websites", "banner": false, "external": "https://indicofishfarm.com/", "photo": "/assets/indicofishfarm-website.jpg", "alt": "Captura da página inicial do website Indico Fish Farm", "desc": "Website corporativo dedicado à produção, processamento de pescado e serviços de aquacultura.", "title": "Indico Fish Farm", "cta": "Explore o projeto", "caseIntro": "A Indico Fish Farm é uma empresa moçambicana dedicada à produção e processamento de pescado. O website apresenta a empresa, os seus serviços e o modelo de negócio no sector da aquacultura.", "caseFeatures": [["Apresentação corporativa", "Missão, visão e valores da empresa."], ["Serviços de aquacultura", "Informação sobre produção, pescado e consultoria técnica."], ["Modelo de negócio", "Apresentação das áreas de atuação e dos mercados."], ["Contacto comercial", "Caminhos para pedidos de informação e reuniões."]]}, {"id": "gawane", "name": "Gawane Consultoria", "type": "Website", "group": "websites", "banner": false, "external": "https://gawaneconsultoria.co.mz/", "photo": "/assets/gawane-site.jpg", "alt": "Colaboração em equipa — imagem do website Gawane", "desc": "Website corporativo de consultoria, análise de dados e formação para pessoas e organizações.", "title": "Gawane Consultoria", "cta": "Explore o projeto", "caseIntro": "A Gawane apresenta soluções de consultoria, análise de dados e formação. O website organiza os serviços e as oportunidades de formação, com uma comunicação centrada nas pessoas e no conhecimento.", "caseFeatures": [["Consultoria", "Apresentação das áreas de serviço para organizações."], ["Análise de dados", "Destaque para a informação no apoio à decisão."], ["Formação", "Divulgação de oportunidades de desenvolvimento de competências."], ["Identidade e contacto", "Apresentação da empresa e contacto para novas necessidades."]]}]);
for(const id of ['sinpeoc','sintrat','gawane'])Object.assign(projects.find(p=>p.id===id),{preview:'/assets/'+id+'-website.jpg'});
for(const [id,caseIntro] of Object.entries({"sweetandsalt": "A Inbytes concebeu e desenvolveu o website da Sweet & Salt, ligando a apresentação da marca ao catálogo de produtos e ao percurso de encomenda. O visitante pode explorar as categorias, selecionar produtos e indicar os detalhes do pedido.", "indicofishfarm": "A Inbytes criou o design e desenvolveu o website da Indico Fish Farm. A apresentação da empresa, os serviços de aquacultura e o modelo de negócio foram organizados numa presença digital com caminhos para contacto comercial.", "gawane": "A Inbytes realizou o design e o desenvolvimento do website da Gawane Consultoria, estruturando a apresentação dos serviços de consultoria, análise de dados e formação e os canais de contacto.", "sinpeoc": "A Inbytes realizou o design e o desenvolvimento do website do SINPEOC. A informação institucional, os serviços aos associados, os documentos e os caminhos de participação foram reunidos numa presença digital para o sindicato."}))projects.find(p=>p.id===id).caseIntro=caseIntro;
const bannerProjects=projects.filter(p=>p.banner!==false);
const projectUrl=p=>routeURL(p.id==='ficha'?'ficha':p.id==='caderneta'?'caderneta':'projeto/'+p.id);
const contactSubjects={projeto:'Novo projeto',websites:'Criação de website',sistemas:'Sistema à medida',apps:'Aplicação móvel',ia:'Inteligência artificial',jmembro:'Demonstração do JMembros',caderneta:'Demonstração da Caderneta',ficha:'Ficha em Dia',sinpocaf:'Projeto SINPOCAF',sintrat:'Projeto SINTRAT',sinpeoc:'Projeto SINPEOC',sweetandsalt:'Projeto Sweet & Salt',indicofishfarm:'Projeto Indico Fish Farm',gawane:'Projeto Gawane',agrario:'Portal Agrário',casas:'Portal Casas'};
function contactURL(subject='projeto'){return routeURL('contactos')+'?assunto='+encodeURIComponent(Object.hasOwn(contactSubjects,subject)?subject:'projeto');}

let slide=0;let heroTimer;let heroPaused;const app=document.querySelector('#app');
const button=(text,url)=>`<a class="btn" href="${url}">${text}<span>↗</span></a>`;
const visual=p=>p.preview?`<img class="website-screenshot" src="${p.preview}" alt="Website ${p.name}" loading="lazy">`:p.photo?`<img class="${['sweetandsalt','indicofishfarm'].includes(p.id)?'website-screenshot':''}" src="${p.photo}" alt="${p.alt}" loading="lazy">`:p.id==='caderneta'?`<img class="caderneta-photo" src="/assets/caderneta-photo.png" alt="Imagem da apresentação da Caderneta Online">`:p.image?`<img src="${photo}" alt="Paisagem agrícola">`:`<div class="mock"><small>inbytes / ${p.name}</small><h4>${p.id==='jmembro'?'Gestão de membros':p.name}</h4><div class="bar"></div><div class="bar"></div><div class="bar"></div><em>${p.id==='jmembro'?'Membros · Quotas · Relatórios':'Uma presença digital com propósito'}</em></div>`;
const cards=arr=>`<div class="grid">${arr.map(p=>`<a class="project" href="${projectUrl(p)}"><div class="visual">${visual(p)}</div><div class="type">${p.type}</div><h3>${p.name} <span style="float:right">↗</span></h3><p>${p.desc}</p></a>`).join('')}</div>`;
const rows=()=>services.map((s,i)=>`<a class="row" href="#/servico/${i}"><span>0${i+1}</span><h3>${s[0]}</h3><p>${s[1]}</p><span>↗</span></a>`).join('');
const art=()=>`<div class="ai-art" aria-hidden="true"><div class="orb"></div><div class="orb"></div><div class="orb"></div><div class="orb"></div><b>IA</b></div>`;
const cta=()=>`<section class="cta"><div class="eyebrow">Vamos construir o próximo passo</div><h2>O seu desafio.<br>A nossa próxima conversa.</h2>${button('Fale connosco','#/contactos')}</section>`;
const pageHead=(label,title,desc='')=>`<section class="page-head"><a class="eyebrow" href="#/">Início / ${label}</a><h1>${title}</h1><p>${desc}</p></section>`;
function bannerIcon(paused){return paused?'<svg viewBox="0 0 24 24" aria-hidden="true" focusable="false"><path d="M8 5v14l11-7z" fill="currentColor"/></svg>':'<svg viewBox="0 0 24 24" aria-hidden="true" focusable="false"><path d="M6 5h4v14H6zm8 0h4v14h-4z" fill="currentColor"/></svg>';}
function hero(){const p=bannerProjects[slide];return `<section class="hero ${p.id==='caderneta'?'education-hero':''}" role="region" aria-roledescription="carousel" aria-label="Destaques"><div class="hero-media">${p.photo?`<img src="${p.photo}" alt="${p.alt}" fetchpriority="high">`:p.image?`<img src="${photo}" alt="Paisagem agrícola">`:`<div class="hero-product-image">${visual(p)}</div>`}</div><div class="hero-copy"><div class="eyebrow">Em destaque / ${p.name}</div><h2>${p.title}</h2><p>${p.desc}</p>${button(p.cta,projectUrl(p))}</div><div class="banner-control-row"><div class="banner-position" aria-live="off">${String(slide+1).padStart(2,'0')} / ${String(bannerProjects.length).padStart(2,'0')}</div><div class="banner-arrows"><button class="banner-prev" type="button" aria-label="Destaque anterior">←</button><button class="banner-next" type="button" aria-label="Destaque seguinte">→</button></div><button class="banner-toggle" type="button" aria-label="Pausar banner" title="Pausar banner" data-paused="false">${bannerIcon(false)}</button></div><div class="tabs" aria-label="Destaques">${bannerProjects.map((x,i)=>`<button data-slide="${i}" class="${i===slide?'active':''}" aria-pressed="${i===slide}"><small>0${i+1} / ${x.id==='caderneta'?'Produto · Educação':x.type}</small><span class="tab-label"><span>${x.id==='jmembro'?'Gestão de Membros':x.id==='caderneta'?'Caderneta':x.name}</span><span class="tab-arrow" aria-hidden="true">↗</span></span></button>`).join('')}</div></section>`}
function editorialOpening(){return `<section class="editorial-opening" aria-label="Inbytes — Desenvolvimento digital"><img class="editorial-image" src="/assets/sinpocaf-hero.jpg" alt="Paisagem ferroviária e portuária — ilustração" width="1600" height="900" fetchpriority="high"><div class="editorial-topline"><span>Inbytes / Desenvolvimento digital</span><span class="opening-index">Design. Engenharia. Continuidade.</span></div><div class="editorial-statement"><div class="editorial-lead"><h1>Websites, sistemas<br>e aplicações.</h1><p class="editorial-description">Ligamos as organizações às pessoas e ao seu trabalho.</p></div><div class="editorial-intro"><p class="editorial-philosophy">Tecnologia para o trabalho de todos os dias.</p><a class="editorial-enquiry" href="${contactURL('projeto')}"><span>Conte-nos o que precisa</span><span class="opening-arrow" aria-hidden="true">↗</span></a></div></div><div class="editorial-baseline"><span>Tecnologia com propósito.</span><a href="#/portfolio">Conheça o trabalho da Inbytes <span aria-hidden="true">↓</span></a></div></section><section class="opening-projects" aria-label="Projetos selecionados"><a class="opening-project opening-project-featured" href="#/projeto/sinpocaf"><img src="/assets/sinpocaf-website.jpg" alt="Website SINPOCAF desenvolvido pela Inbytes" width="1265" height="712"><span class="opening-project-copy"><small>01 / Website institucional</small><strong>SINPOCAF</strong></span><span class="project-arrow" aria-hidden="true">↗</span></a><a class="opening-project" href="#/projeto/sweetandsalt"><span class="opening-project-copy"><small>02 / Catálogo e encomendas</small><strong>Sweet & Salt</strong></span><span class="project-arrow" aria-hidden="true">↗</span></a><a class="opening-project" href="#/projeto/jmembro"><span class="opening-project-copy"><small>03 / Sistema de gestão</small><strong>JMembros</strong></span><span class="project-arrow" aria-hidden="true">↗</span></a></section>`;}
function home(){return editorialOpening()+`<section class="section services"><div class="head"><div><div class="eyebrow">O que fazemos</div><h2>Uma necessidade concreta.<br>A solução certa.</h2></div><a class="link" href="#/servicos">Explore os serviços ↗</a></div>${rows()}</section>`+hero()+`<section class="section selected-work"><div class="head"><div><div class="eyebrow">Trabalho selecionado</div><h2>Conheça o que<br>já construímos.</h2></div><a class="link" href="#/portfolio">Ver todo o portefólio ↗</a></div>${cards([projects.find(p=>p.id==='jmembro'),projects.find(p=>p.id==='sweetandsalt'),projects.find(p=>p.id==='sinpeoc'),projects.find(p=>p.id==='agrario')])}</section><section class="section ai"><div><span class="badge">INTELIGÊNCIA ARTIFICIAL</span><h2>Começar pelo problema.<br>Encontrar valor na IA.</h2><p>Atendimento, documentos e tarefas repetitivas: identifique onde a inteligência artificial pode apoiar a sua equipa e o que é necessário para a aplicar.</p>${button('Converse sobre IA',contactURL('ia'))}<a class="link ai-link" href="#/ia">Conheça a abordagem ↗</a></div>${art()}</section><section class="section working-method"><div class="eyebrow">Como trabalhamos</div><h2>Clareza em cada etapa.</h2><div class="steps"><article><span>01</span><h3>Compreender</h3><p>Conversamos sobre o objetivo, os utilizadores e os processos.</p></article><article><span>02</span><h3>Construir</h3><p>Definimos o âmbito e partilhamos o progresso para validar a solução.</p></article><article><span>03</span><h3>Acompanhar</h3><p>Preparamos a adoção e acordamos o apoio necessário à continuidade.</p></article></div></section>`+cta()}

function cadernetaPage(){return `<section class="caderneta-hero"><div><span class="eyebrow">Um produto Inbytes / Educação</span><img class="product-logo" src="/assets/caderneta-logo.svg" alt="Caderneta Online"><h1>A escola mais perto.<br>O futuro mais claro.</h1><p>A gestão da sua escola e o acompanhamento académico pelos encarregados de educação, em tempo real.</p>${button('Pedir uma demonstração',contactURL('caderneta'))}<button class="link feature-scroll" type="button">Conheça as funcionalidades ↓</button></div><div class="caderneta-picture"><img src="/assets/caderneta-photo.png" alt="Imagem promocional original da Caderneta Online"></div></section><section class="section intro"><div class="eyebrow">Escola. Família. Aluno.</div><div><h2>Uma ligação que acompanha<br>cada etapa da aprendizagem.</h2><p>A Caderneta Online é um produto da Inbytes que reúne informação académica e permite à escola e aos encarregados acompanhar o percurso dos alunos pela internet.</p></div></section><section id="funcionalidades" class="section services"><div class="eyebrow">O que pode fazer</div><h2>O essencial da vida escolar.<br>Num só lugar.</h2><div class="grid">${[['01','Registo académico','Registar notas, médias, faltas e TPCs através do telemóvel ou computador.'],['02','Alertas aos encarregados','Comunicar datas e resultados de avaliações e ocorrências registadas pela escola, por telefone ou email.'],['03','Acompanhamento individual','Consultar o aproveitamento, as próximas avaliações e o registo dos TPCs dos educandos.'],['04','Pautas e relatórios','Consultar informação académica e gerar e imprimir pautas por turma ou por aluno.'],['05','Acesso pela internet','Acesso individual com utilizador e palavra-passe para consultar a informação disponível ao respetivo perfil.'],['06','Adaptação à escola','Adequar a solução aos processos e necessidades específicas de cada escola.']].map(x=>`<article class="feature"><span class="eyebrow">${x[0]}</span><h3>${x[1]}</h3><p>${x[2]}</p></article>`).join('')}</div></section><section class="section"><div class="eyebrow">Como funciona</div><h2>Da sala de aula<br>ao encarregado de educação.</h2><div class="steps"><article><span>01</span><h3>A escola regista</h3><p>Professores ou secretaria selecionam a turma e registam avaliações, notas, faltas e TPCs.</p></article><article><span>02</span><h3>A informação chega</h3><p>Os encarregados recebem alertas sobre os registos relativos aos seus educandos.</p></article><article><span>03</span><h3>Todos acompanham</h3><p>Os encarregados consultam o percurso académico e a secretaria acompanha os alunos e emite pautas.</p></article></div></section><section class="section ai"><div><span class="eyebrow">Para a sua instituição</span><h2>Vamos aproximar<br>a escola das famílias?</h2><p>Converse com a Inbytes para conhecer a Caderneta Online e avaliar a sua implementação na sua escola.</p>${button('Fale sobre a sua escola',contactURL('caderneta'))}</div><div><h3>Uma solução. Três perspetivas.</h3><p>Professores: registo e acompanhamento das turmas.</p><p>Secretaria: consulta de dados académicos e pautas.</p><p>Encarregados: informação sobre o percurso dos educandos.</p></div></section>`;}


const fichaProduct={id:'ficha',name:'Ficha em Dia',type:'Produto Inbytes · Educação',photo:'/assets/ficha-familia.png',alt:'Pais a preencher os dados no telemóvel, com a filha e um computador, junto à escola',desc:'Inscrições e atualização dos dados dos alunos. Os pais preenchem e a escola recebe os dados organizados em Excel.'};
function portfolioGroups(productsOnly=false){return [['produtos','Produtos e Sistemas','Ferramentas para o dia a dia das organizações.'],['portais','Portais','Plataformas que aproximam pessoas, mercados e oportunidades.'],['websites','Websites e plataformas','Presenças digitais para instituições e organizações.']].filter(x=>!productsOnly||x[0]==='produtos').map(([id,title,desc])=>`<section class="portfolio-group"><div class="eyebrow">${title}</div><h3>${desc}</h3>${cards(projects.filter(p=>p.group===id).concat(id==='produtos'?[fichaProduct]:[]))}</section>`).join('')}
const featureGrid=items=>`<div class="grid">${items.map(([t,d],i)=>`<article class="feature"><span class="eyebrow">0${i+1}</span><h3>${t}</h3><p>${d}</p></article>`).join('')}</div>`;
function casePresentation(p){
 const facts=`<section class="section case-summary"><div class="eyebrow">O trabalho da Inbytes</div><div class="case-facts"><article><h3>Design</h3><p>Conceção da apresentação e da experiência de navegação.</p></article><article><h3>Desenvolvimento</h3><p>Implementação das funcionalidades apresentadas neste projeto.</p></article><article><h3>${p.group==='websites'?'Website e plataforma':'Produto e solução'}</h3><p>${p.desc}</p></article></div></section>`;
 const screenshot=Boolean(p.preview)||['sweetandsalt','indicofishfarm'].includes(p.id);
 return facts+(screenshot?`<section class="section case-preview"><div class="eyebrow">O projeto em imagem</div><div class="browser-card"><div class="browser-bar"><i></i><i></i><i></i><span>${p.external.replace(/^https?:\/\//,'').replace(/\/$/,'')}</span></div>${visual(p)}</div></section>`:'');
}
function projectPage(p){if(p.id==='caderneta')return cadernetaPage();const head=`<section class="case-hero clean-case"><div class="case-title"><a class="eyebrow" href="#/portfolio">Portefólio / ${p.group==='portais'?'Portais':p.group==='produtos'?'Produtos e Sistemas':'Websites e plataformas'}</a><h1>${p.name}</h1><p>${p.desc}</p>${button(p.id==='jmembro'?'Pedir uma demonstração':'Fale sobre o seu projeto',contactURL(p.id))}${p.external?`<a class="link" href="${p.external}" target="_blank" rel="noopener">Visite o website ↗</a>`:''}</div></section>`+casePresentation(p);
if(p.id==='jmembro')return head+`<section class="section intro"><div class="eyebrow">Gestão de membros</div><div><h2>Conhecer os membros.<br>Acompanhar a organização.</h2><p>O JMembros centraliza informação de membros, empresas e contribuições. Facilita a pesquisa e atualização dos registos e permite acompanhar ocorrências de forma estruturada.</p><p>Uma base comum para apoiar o trabalho administrativo e as decisões internas.</p></div></section><section class="section services"><div class="eyebrow">Funcionalidades</div><h2>Da inscrição<br>ao acompanhamento.</h2>${featureGrid([['Base de dados de membros','Cadastro, consulta, atualização e organização dos membros numa base eletrónica.'],['Empresas filiadas','Registo institucional das empresas e histórico de relacionamento.'],['Contribuições e pagamentos','Controlo de valores canalizados, movimentos e histórico financeiro.'],['Ocorrências e denúncias','Registo e acompanhamento interno de acidentes e denúncias.'],['Relatórios quantitativos','Estatísticas de membros, empresas, acidentes e valores para apoiar a gestão.'],['Auto-registo e pesquisa','Recolha e atualização de dados com ferramentas de pesquisa.']])}</section><section class="section"><div class="eyebrow">Como funciona</div><h2>Informação que acompanha<br>o trabalho da equipa.</h2><div class="steps"><article><span>01</span><h3>Organizar</h3><p>Registar membros e empresas e manter a informação atualizada.</p></article><article><span>02</span><h3>Acompanhar</h3><p>Consultar contribuições, movimentos financeiros e ocorrências.</p></article><article><span>03</span><h3>Analisar</h3><p>Usar relatórios quantitativos para acompanhar a atividade e apoiar decisões.</p></article></div></section><section class="section ai"><div><div class="eyebrow">Acesso e implementação</div><h2>Uma utilização ajustada<br>à sua organização.</h2><p>Os níveis de permissão e o âmbito de acesso são definidos para a implementação. A expansão a outras delegações e os serviços de manutenção e apoio são acordados com a organização.</p>${button('Converse connosco',contactURL('jmembro'))}</div><div><h3>Começamos pela sua realidade.</h3><p>Validamos as necessidades, os perfis de utilização e as condições de implementação antes de criar os acessos.</p><p>As funcionalidades apresentadas seguem a documentação técnica do JMembros; a configuração final depende do âmbito acordado.</p></div></section>`;
if(p.caseIntro)return head+`<section class="section intro"><div class="eyebrow">O projeto</div><div><h2>Design e desenvolvimento<br>para uma necessidade real.</h2><p>${p.caseIntro}</p></div></section><section class="section services"><div class="eyebrow">Funcionalidades do projeto</div><h2>Uma experiência pensada<br>para os utilizadores.</h2>${featureGrid(p.caseFeatures)}</section>`+cta();
if(p.group==='websites'){const sintrat=p.id==='sintrat';return head+`<section class="section intro"><div class="eyebrow">O projeto</div><div><h2>Uma presença digital<br>ao serviço da instituição.</h2><p>${sintrat?'O SINTRAT representa trabalhadores dos transportes rodoviários, assistência técnica e similares em Moçambique. O seu website apresenta a instituição, os serviços sindicais e os caminhos de adesão.':'O website do SINPOCAF integra o conjunto de projetos institucionais desenvolvido pela Inbytes no âmbito da sua unidade de criação de websites.'}</p><p>Em 2025, a Inbytes desenvolveu os websites do SINPOCAF, SINPEOC e SINTRAT por adjudicação da International Transport Federation.</p></div></section><section class="section services"><div class="eyebrow">${sintrat?'O que o website apresenta':'Contexto e abordagem'}</div><h2>Comunicação clara.<br>Uma instituição mais próxima.</h2>${featureGrid(sintrat?[['Identidade institucional','Apresentação do sindicato, dos setores representados e dos seus princípios.'],['Serviços aos associados','Informação sobre assistência jurídica e laboral, formação e negociação coletiva.'],['Adesão ao sindicato','Explicação das etapas de inscrição e acesso aos benefícios sindicais.'],['Contacto e atividade','Canais de contacto, formulário de pedido e divulgação de eventos.']]:[['Presença institucional','Um projeto de website para a comunicação da organização na internet.'],['Projeto integrado','Um dos projetos institucionais desenvolvidos pela Inbytes.'],['Conceção de websites','Trabalho enquadrado na unidade especializada criada em 2025.'],['Continuidade','Uma base digital que pode evoluir com as necessidades da instituição.']])}</section><section class="section detail"><h2>Da compreensão<br>à implementação.</h2><p>A metodologia da Inbytes começa pela análise da atividade e dos objetivos do cliente, segue pela validação da solução e do cronograma e inclui acompanhamento durante o desenvolvimento, formação e apoio à adoção.</p></section>`+cta();}
return head+`<section class="section intro"><div class="eyebrow">Portal / ${p.id==='casas'?'Imobiliário':'Agricultura'}</div><div><h2>${p.id==='casas'?'Novos espaços.<br>Novas oportunidades.':'Uma ligação digital<br>ao mercado agrícola.'}</h2><p>${p.id==='casas'?'O Casas é um portal de promoção imobiliária em Moçambique. Apresenta imóveis para venda e arrendamento, com informação que ajuda o visitante a explorar as ofertas disponíveis.':'O Agrário é uma plataforma online de divulgação e promoção da comercialização agrícola em Moçambique.'}</p></div></section><section class="section services">${featureGrid(p.id==='casas'?[['Venda e arrendamento','Exploração de ofertas de imóveis para comprar ou arrendar.'],['Pesquisa de imóveis','Pesquisa e filtros para encontrar ofertas no portal.'],['Detalhes das propriedades','Informação de localização, características, fotografias e valores dos anúncios.'],['Contacto','Canais para conversar sobre promoção e divulgação de imóveis.']]:[['Divulgação agrícola','Uma presença digital dedicada ao sector agrário moçambicano.'],['Promoção da comercialização','Plataforma orientada à divulgação de oportunidades no mercado agrícola.']])}</section><section class="section detail"><h3>Explore o portal</h3><p>Conheça a plataforma no seu endereço próprio.</p>${button('Visite '+p.name,p.external)}</section>`+cta();}
function aboutPage(){return pageHead('Sobre a Inbytes','Sobre a Inbytes.<br>Tecnologia com propósito.','Uma empresa moçambicana dedicada ao desenvolvimento e comercialização de sistemas de informação.')+`<section class="section intro"><div class="eyebrow">Quem somos</div><div><h2>O seu negócio<br>é o nosso ponto de partida.</h2><p>Desenhamos soluções e criamos produtos digitais que ajudam os nossos clientes a inovar, automatizar processos e melhorar o seu trabalho.</p><p>A nossa cultura assenta na inovação, na colaboração e na confiança. Procuramos relações duradouras e soluções ajustadas à atividade de cada organização.</p></div></section><section class="section services">${featureGrid([['A nossa visão','Impulsionar a transformação digital, melhorar processos e apoiar o crescimento sustentável através da tecnologia.'],['A nossa missão','Fornecer sistemas à medida das necessidades específicas de cada cliente, preparando a organização para os desafios atuais e futuros.']])}</section><section class="section"><div class="eyebrow">O nosso percurso</div><h2>Experiência que<br>se transforma em soluções.</h2><div class="timeline">${[['2017','Sistemas para projetos','Desenho de arquitetura e criação de sistemas para projetos da Johns Hopkins University — CCP, com colaboração prolongada até 2023.'],['2020','Implementação e acompanhamento','Projetos para GIZ e VIDA, com aconselhamento, desenho da solução, implementação, formação e suporte.'],['2023','Caderneta Online','Investimento próprio numa solução de gestão escolar e acompanhamento académico.'],['2025','Websites institucionais','Criação de uma unidade especializada em websites e projetos para SINPOCAF, SINPEOC e SINTRAT.']].map(x=>`<article><span>${x[0]}</span><div><h3>${x[1]}</h3><p>${x[2]}</p></div></article>`).join('')}</div></section><section class="section services"><div class="eyebrow">Como trabalhamos</div><h2>Escutar. Construir.<br>Acompanhar.</h2>${featureGrid([['Análise e aconselhamento','Compreendemos a atividade e os objetivos do cliente antes de propor a solução.'],['Validação e planeamento','Validamos a solução e o cronograma antes do desenvolvimento.'],['Desenvolvimento acompanhado','Partilhamos o progresso e recolhemos comentários durante a construção.'],['Formação e suporte','Apoiamos a instalação, a formação dos utilizadores e a adoção da solução.']])}</section>`+cta();}

let turnstileLoader;
function loadTurnstile(){if(window.turnstile)return Promise.resolve();if(!turnstileLoader)turnstileLoader=new Promise((resolve,reject)=>{window.inbytesTurnstileReady=resolve;let script=document.createElement('script');script.src='https://challenges.cloudflare.com/turnstile/v0/api.js?onload=inbytesTurnstileReady&render=explicit';script.async=true;script.onerror=()=>{turnstileLoader=null;reject(Error('Antispam indisponível.'));};document.head.append(script);});return turnstileLoader;}
async function setupContactForm(form){
 const status=form.querySelector('#feedback'),submit=form.querySelector('[type="submit"]');let token='',widget;
 if(['localhost','127.0.0.1'].includes(location.hostname)){submit.disabled=false;status.textContent=window.siteTranslate('Pré-visualização local: o envio de mensagens está desativado.');form.onsubmit=event=>{event.preventDefault();if(form.reportValidity())status.textContent=window.siteTranslate('Formulário validado localmente. Nenhuma mensagem foi enviada.');};return;}
 status.textContent=window.siteTranslate('A preparar o formulário…');
 try{const response=await fetch('/api/contact-config',{cache:'no-store'});if(!response.ok)throw Error();const config=await response.json();if(!config.siteKey)throw Error();await loadTurnstile();if(!form.isConnected)return;
 widget=window.turnstile.render(form.querySelector('#contact-challenge'),{sitekey:config.siteKey,language:window.siteLanguage==='en'?'en':'pt',size:window.innerWidth<360?'compact':'normal',action:'contact',callback:value=>{token=value;submit.disabled=false;status.textContent=window.siteTranslate('');},'expired-callback':()=>{token='';submit.disabled=true;},'error-callback':()=>{token='';submit.disabled=true;status.textContent=window.siteTranslate('Não foi possível validar o antispam. Atualize a página.');}});
 }catch{status.textContent=window.siteTranslate('Formulário indisponível. Contacte info@inbytes.co.mz ou telefone para +258 84 602 5532.');return;}
 form.onsubmit=async event=>{event.preventDefault();if(!token||!form.reportValidity())return;submit.disabled=true;status.textContent=window.siteTranslate('A enviar…');const fields=new FormData(form);
 try{const response=await fetch('/api/contact',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({nome:fields.get('nome'),email:fields.get('email'),empresa:fields.get('empresa'),mensagem:'Assunto: '+(contactSubjects[fields.get('assunto')]||contactSubjects.projeto)+'\n\n'+fields.get('mensagem'),website:fields.get('website'),token}),signal:AbortSignal.timeout(40000)});const result=await response.json();if(!response.ok)throw Error(result.error||'Não foi possível enviar.');status.textContent=window.siteTranslate(result.message);form.reset();}
 catch(error){status.textContent=window.siteTranslate(error.name==='TimeoutError'?'O envio demorou mais do que o esperado. Verifique com a Inbytes antes de repetir.':error.message||'Não foi possível enviar. Tente novamente.');}
 finally{token='';if(form.isConnected)window.turnstile.reset(widget);}
 };
}

function paintHero(){
 const root=document.querySelector('.hero');if(!root)return;
 const template=document.createElement('template');template.innerHTML=siteLinks(hero());
 root.querySelector('.hero-media').innerHTML=template.content.querySelector('.hero-media').innerHTML;
 root.querySelector('.hero-copy').innerHTML=template.content.querySelector('.hero-copy').innerHTML;
 const position=root.querySelector('.banner-position');if(position)position.textContent=String(slide+1).padStart(2,'0')+' / '+String(bannerProjects.length).padStart(2,'0');
 root.querySelectorAll('[data-slide]').forEach(button=>{const active=Number(button.dataset.slide)===slide;button.classList.toggle('active',active);button.setAttribute('aria-pressed',String(active));});
 window.applySiteLanguage();
}
function setupHero(){
 if(heroTimer)clearTimeout(heroTimer);
 const root=document.querySelector('.hero');if(!root)return;
 if(heroPaused===undefined)heroPaused=Boolean(window.matchMedia?.('(prefers-reduced-motion: reduce)').matches);
 const schedule=()=>{if(heroTimer)clearTimeout(heroTimer);if(heroPaused)return;
 heroTimer=setTimeout(()=>{if(!root.isConnected)return;const box=root.getBoundingClientRect();const keyboardFocus=root.contains(document.activeElement)&&document.activeElement?.matches(':focus-visible');if(!document.hidden&&!keyboardFocus&&box.bottom>0&&box.top<window.innerHeight){slide=(slide+1)%bannerProjects.length;paintHero();}schedule();},7000);
 };
 const toggle=root.querySelector('.banner-toggle');
 const updateToggle=()=>{toggle.innerHTML=bannerIcon(heroPaused);toggle.dataset.paused=String(heroPaused);const label=window.siteTranslate(heroPaused?'Retomar banner':'Pausar banner');toggle.setAttribute('aria-label',label);toggle.setAttribute('title',label);toggle.setAttribute('aria-pressed',String(heroPaused));};
 toggle.onclick=()=>{heroPaused=!heroPaused;updateToggle();schedule();};updateToggle();
 root.querySelectorAll('[data-slide]').forEach(button=>{button.onclick=()=>{slide=Number(button.dataset.slide);paintHero();schedule();};});
 const move=delta=>{slide=(slide+delta+bannerProjects.length)%bannerProjects.length;paintHero();schedule();};
 const previous=root.querySelector('.banner-prev'),next=root.querySelector('.banner-next');if(previous)previous.onclick=()=>move(-1);if(next)next.onclick=()=>move(1);
 schedule();
}

