const serviceContent=[{"title": "Criação de websites profissionais", "intro": "Um website deve ajudar os clientes a conhecer a sua empresa e a dar o próximo passo. A Inbytes desenvolve websites para empresas e instituições, com uma apresentação cuidada e uma navegação clara.", "heading": "O website certo para a sua organização", "features": [["Websites institucionais", "Apresente a empresa, os serviços, a equipa e os contactos com uma navegação clara, adaptada a computadores e telemóveis."], ["Catálogos e encomendas", "Organize os produtos e defina o percurso de contacto ou encomenda. As funcionalidades de carrinho e pagamento são avaliadas conforme o projeto."], ["Portais e conteúdos", "Estruture anúncios, informação e oportunidades para um público específico. Agrário e Casas são exemplos do nosso portefólio."]], "projects": ["sinpeoc", "sweetandsalt", "indicofishfarm"], "faqs": [["Quanto custa criar um website?", "O orçamento depende do número de páginas, dos conteúdos, das funcionalidades e das integrações. Diga-nos o que precisa para prepararmos uma proposta com âmbito e custos definidos."], ["Já tenho um website. Posso renová-lo?", "Podemos avaliar o website atual e planear a renovação dos conteúdos, da navegação e da apresentação. Domínio, alojamento e endereços existentes são considerados no planeamento."]]}, {"title": "Desenvolvimento de sistemas à medida", "intro": "Quando a informação está dispersa, a gestão torna-se mais difícil. A Inbytes desenvolve sistemas de informação à medida e apresenta produtos próprios para necessidades específicas de empresas e instituições.", "heading": "Da atividade da organização ao sistema", "features": [["Processos e informação", "Começamos por compreender os registos, os utilizadores e as tarefas. O âmbito define o que será centralizado, automatizado ou integrado."], ["Gestão de associados", "O JMembros reúne membros, empresas, contribuições e ocorrências. Conheça o produto e converse connosco sobre a adequação à sua organização."], ["Informação escolar", "A Caderneta Online apoia o acompanhamento académico. A Ficha em Dia organiza a recolha e atualização de dados dos alunos com entrega em Excel."]], "projects": ["jmembro", "caderneta", "ficha"], "faqs": [["Produto existente ou sistema à medida?", "Primeiro avaliamos a necessidade. Um produto pode responder a processos já cobertos; um desenvolvimento à medida exige definir requisitos, integrações e manutenção. A proposta esclarece a abordagem."], ["É possível integrar com outros sistemas?", "A integração depende das interfaces, permissões e condições técnicas das plataformas envolvidas. Avaliamos a viabilidade antes de assumir essa entrega."]]}, {"title": "Desenvolvimento de apps", "intro": "Uma aplicação começa numa necessidade concreta dos utilizadores. A Inbytes recebe projetos de aplicações móveis para empresas e instituições, com análise do contexto, dos dispositivos e da ligação aos sistemas existentes.", "heading": "Antes de desenvolver, definir a experiência", "features": [["Utilizadores e tarefas", "Que tarefa deve ser possível realizar no telemóvel? Identificamos os percursos essenciais e os dados necessários para definir a primeira versão."], ["Plataformas e conectividade", "A escolha entre aplicação móvel e plataforma web depende do público, dos dispositivos, da conectividade e do orçamento. Essa decisão é tomada durante a análise."], ["Integração e evolução", "Requisitos de acesso, ligação a sistemas, publicação e manutenção são definidos na proposta. Funcionalidades adicionais são planeadas conforme as prioridades."]], "projects": [], "faqs": [["Preciso de uma app ou de um website?", "Depende das tarefas e da frequência de utilização. Um website adaptado ao telemóvel pode ser suficiente; uma app pode fazer sentido quando existem necessidades específicas do dispositivo. A análise ajuda a decidir."], ["Quanto tempo demora desenvolver uma app?", "O prazo depende do âmbito, das integrações, dos conteúdos e da validação. Após compreender os requisitos, a proposta apresenta as etapas e o cronograma."]]}];
function servicePage(index){
 const d=serviceContent[index],s=services[index];
 if(!d)return s?pageHead('Serviços',s[0],s[1])+`<section class="section detail"><h2>Começamos por compreender o seu contexto.</h2><p>Conversamos sobre utilizadores, processos, prioridades e integrações. A proposta define o âmbito, as entregas e o acompanhamento necessário.</p>${button('Fale sobre o seu projeto','#/contactos')}</section>`:pageHead('Página','Página não encontrada');
 const related=d.projects.map(id=>id==='ficha'?fichaProduct:projects.find(p=>p.id===id)).filter(Boolean);
 return pageHead('Serviços',d.title,d.intro)+`<section class="section services"><h2>${d.heading}</h2>${featureGrid(d.features)}</section><section class="section detail"><h2>Como avançamos com o seu projeto</h2><p>Partilhe o objetivo, quem vai utilizar a solução e o que já existe. Analisamos as necessidades e apresentamos uma proposta antes de iniciar o desenvolvimento.</p>${button('Pedir orçamento',contactURL(['websites','sistemas','apps'][index]||'projeto'))}</section>`+(related.length?`<section class="section"><h2>Projetos relacionados</h2>${cards(related)}</section>`:'')+`<section class="section services"><h2>Perguntas sobre este serviço</h2><div class="service-faq">${d.faqs.map(([question,answer])=>`<article><h3>${question}</h3><p>${answer}</p></article>`).join('')}</div></section><section class="section detail"><h2>Peça uma proposta à Inbytes</h2><p>Fale connosco sobre o seu projeto. Indique as funcionalidades pretendidas e, se possível, exemplos e prioridades.</p>${button('Pedir orçamento',contactURL(['websites','sistemas','apps'][index]||'projeto'))}</section>`;
}


function contactPage(){
 const selected=new URLSearchParams(location.search||'').get('assunto');const subject=Object.hasOwn(contactSubjects,selected)?selected:'projeto';
 return pageHead('Contactos','O próximo passo<br>começa numa conversa.','Conte-nos o que pretende construir, melhorar ou simplificar. A Inbytes ajuda a definir o caminho.')+`<section class="section contact-panel"><div><div class="eyebrow">Fale com a Inbytes</div><h2>Uma ideia, um desafio<br>ou uma demonstração.</h2><p>Partilhe o objetivo e o contexto da sua organização. Se já conhece um dos nossos produtos, selecione-o no formulário.</p><p><a class="link" href="mailto:info@inbytes.co.mz">info@inbytes.co.mz ↗</a><br><a class="link" href="tel:+258846025532">+258 84 602 5532</a><br><a class="link" href="tel:+258872414841">+258 87 241 4841</a></p><p>Rua Dona Leonor 89 RC · Maputo</p></div><form id="form"><label>Como podemos ajudar?<select name="assunto">${Object.entries(contactSubjects).map(([key,label])=>`<option value="${key}" ${key===subject?'selected':''}>${label}</option>`).join('')}</select></label><label>Nome<input name="nome" minlength="2" maxlength="120" required autocomplete="name"></label><label>Email<input name="email" type="email" maxlength="254" required autocomplete="email"></label><label>Organização<input name="empresa" maxlength="160" autocomplete="organization"></label><label>Conte-nos o seu desafio<textarea name="mensagem" minlength="10" maxlength="5600" required placeholder="Objetivo, utilizadores e funcionalidades pretendidas"></textarea></label><label class="honeypot" aria-hidden="true">Website<input name="website" tabindex="-1" autocomplete="off"></label><p class="privacy-note">Usaremos os dados que indicar para responder ao seu pedido. <a href="#/privacidade">Saiba como tratamos os seus dados.</a></p><div id="contact-challenge"></div><button class="btn" type="submit" disabled>Enviar mensagem <span>↗</span></button><p id="feedback" role="status" aria-live="polite"></p></form></section>`;
}
function privacyPage(){return pageHead('Privacidade','Privacidade e contacto.','Informação sobre os dados enviados através deste website.')+`<section class="section privacy-copy"><h2>Os dados que nos envia</h2><p>O formulário recolhe o nome, o endereço de email, a organização, quando indicada, o assunto e a mensagem. Utilizamos esta informação para compreender o pedido e responder ao contacto.</p><h2>Envio e proteção do formulário</h2><p>As mensagens são encaminhadas por email para a Inbytes. O envio utiliza a Resend e a proteção contra spam utiliza o Cloudflare Turnstile. Estes serviços intervêm no processamento técnico do pedido.</p><p>O website aplica limites de envio para reduzir abusos. Não envie palavras-passe, documentos de identificação ou outra informação sensível através deste formulário.</p><h2>Preferência de idioma</h2><p>A versão portuguesa e a versão inglesa têm endereços próprios. Ao mudar de idioma, mantém-se na página correspondente.</p><h2>Questões sobre os seus dados</h2><p>Para esclarecer a utilização dos dados que nos enviou ou pedir a sua correção ou eliminação, contacte a Inbytes através de <a class="link" href="mailto:info@inbytes.co.mz">info@inbytes.co.mz</a>.</p></section>`;}
function aiPage(){return pageHead('Inteligência Artificial','IA aplicada<br>ao seu contexto.','O primeiro passo é perceber o problema, os dados disponíveis e o papel das pessoas. Depois, avaliar onde a IA acrescenta valor.')+`<section class="section intro"><div class="eyebrow">Começar com clareza</div><div><h2>Um objetivo definido.<br>Uma decisão informada.</h2><p>Automatizar uma tarefa ou apoiar uma decisão exige mais do que escolher uma ferramenta. É preciso definir o que deve melhorar, quais as fontes de informação e como validar as respostas.</p>${button('Fale sobre o seu desafio',contactURL('ia'))}</div></section><section class="section services"><div class="eyebrow">Exemplos de aplicação</div><h2>Onde procurar oportunidades.</h2>${featureGrid([['Atendimento e pesquisa','Assistentes que procuram respostas em informação aprovada pela organização, com encaminhamento para uma pessoa quando necessário.'],['Leitura de documentos','Pesquisa, classificação e síntese de documentos para apoiar o trabalho da equipa.'],['Processos repetitivos','Identificação de tarefas que podem ser apoiadas por automatização, com validação humana.'],['Plataformas empresariais','Avaliação da ligação entre funcionalidades de IA e os sistemas utilizados pela organização.']])}<p class="case-proof">Estes exemplos descrevem aplicações possíveis. A adequação, a implementação e os custos dependem de uma avaliação do caso concreto.</p></section><section class="section"><div class="eyebrow">O que precisamos de avaliar</div><h2>Dados, qualidade<br>e responsabilidade.</h2><div class="steps"><article><span>01</span><h3>Objetivo e dados</h3><p>Que tarefa queremos melhorar? Que informação existe e pode ser utilizada?</p></article><article><span>02</span><h3>Validação e acesso</h3><p>Como serão verificadas as respostas e quem terá acesso à informação?</p></article><article><span>03</span><h3>Integração e operação</h3><p>Como se liga a solução ao trabalho da equipa e quais os custos de utilização?</p></article></div></section>`+cta();}

function render(){const currentURL=location.pathname.replace(/^\/en(?=\/|$)/,'').replace(/index\.html$/,'').replace(/\/?$/,'/');const route=window.siteRoutes.find(r=>r.path===currentURL);const key=location.hash.startsWith('#/')?location.hash.slice(2):(route?.key??'__missing');const path=key.split('/');let out='';if(!path[0])out=home();else if(path[0]==='ficha')out=fichaPage();else if(path[0]==='caderneta')out=cadernetaPage();else if(path[0]==='sobre')out=aboutPage();else if(path[0]==='servicos')out=pageHead('Serviços','Do desafio<br>à solução.')+`<section class="section services">${rows()}</section>`+cta();else if(path[0]==='servico')out=servicePage(Number(path[1]));else if(path[0]==='ia')out=aiPage();else if(path[0]==='privacidade')out=privacyPage();else if(['produtos','portfolio'].includes(path[0]))out=pageHead(path[0]==='produtos'?'Soluções':'Portefólio',path[0]==='produtos'?'Soluções para<br>necessidades reais.':'O nosso trabalho.<br>O seu próximo passo.')+`<section class="section">${portfolioGroups(path[0]==='produtos')}</section>`+cta();else if(path[0]==='projeto'){let p=projects.find(x=>x.id===path[1]);out=p?projectPage(p):pageHead('Página','Projeto não encontrado');}else if(path[0]==='contactos')out=contactPage();else out=pageHead('Página','Página não encontrada')+button('Voltar ao início','#/');app.innerHTML=siteLinks(out);const featuresButton=document.querySelector('.feature-scroll');if(featuresButton)featuresButton.onclick=()=>document.querySelector('#funcionalidades').scrollIntoView();window.currentSEO=window.siteRoutes.find(r=>r.key===key)||{title:'Página não encontrada — Inbytes',description:''};document.title=window.currentSEO.title;const canonical=document.querySelector('link[rel=canonical]');if(canonical&&route)canonical.href='https://inbytes.co.mz'+(window.siteLanguage==='en'?'/en':'')+route.path;document.querySelector('nav').classList.remove('open');document.querySelector('#menu').setAttribute('aria-expanded','false');setupHero();let f=document.querySelector('#form');if(f)setupContactForm(f);window.applySiteLanguage();}

window.addEventListener('hashchange',()=>{render();window.scrollTo(0,0)});document.querySelector('#menu').onclick=()=>{let n=document.querySelector('nav');n.classList.toggle('open');document.querySelector('#menu').setAttribute('aria-expanded',String(n.classList.contains('open')))};render();
